import {example,validate,tokenize,toTikz,matcher,isAccepting,setAccepting} from './lexer.js';
import {autoLayout,routeEdges} from './layout.js';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let machine=example(),selection={type:'state',id:'s1'},source=null,history=[],future=[];
try{const saved=localStorage.getItem('lexica-machine');if(saved)machine=validate(JSON.parse(saved))}catch{toast('Could not restore saved machine. Example loaded.')}
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').style.display='none',3500)}
function checkpoint(){history.push(JSON.stringify(machine));if(history.length>80)history.shift();future=[]}
function save(){try{localStorage.setItem('lexica-machine',JSON.stringify(machine));document.querySelector('.local').innerHTML='<i></i> Saved locally'}catch{document.querySelector('.local').textContent='Storage unavailable — export to save'}}
function changed(){save();render()}
function render(){if(selection.type==='state'&&!machine.states.some(s=>s.id===selection.id))selection={type:'state',id:machine.start??machine.states[0].id};$('machine-info').textContent=`${machine.states.length} states · ${machine.edges.length} transitions`;
 draw();drawMap();properties();test();$('undo').disabled=!history.length;$('redo').disabled=!future.length;
}
function draw(){let html='';const routes=routeEdges(machine);for(let i=0;i<machine.edges.length;i++){const e=machine.edges[i],r=routes[i];html+=`<g data-edge="${i}"><path class="edge ${selection.type==='edge'&&selection.index===i?'selected-edge':''}" d="${r.d}"/><path class="edge-hit" d="${r.d}"/><text class="edge-text" x="${r.label.x}" y="${r.label.y}" text-anchor="middle">${esc(e.label)}</text></g>`}
 for(const s of machine.states){if(s.id===machine.start)html+=`<path class="edge" d="M ${s.x-85} ${s.y} L ${s.x-40} ${s.y}"/>`;html+=`<g class="node ${selection.type==='state'&&selection.id===s.id?'selected':''} ${source===s.id?'connecting':''}" data-node="${esc(s.id)}" transform="translate(${s.x} ${s.y})"><circle r="36"/>${isAccepting(s)?'<circle class="inner" r="31"/>':''}<text y="4" ${s.name.length>10?'textLength="60" lengthAdjust="spacingAndGlyphs"':''}>${esc(s.name)}</text>${isAccepting(s)?`<text class="token-label" y="57">${esc(s.token)}${s.skip?' · skip':''}</text>`:''}</g>`}
 if(source){const a=machine.states.find(s=>s.id===source);if(a&&connectPoint)html+=`<path class="connection-preview" d="M ${a.x} ${a.y} L ${connectPoint.x} ${connectPoint.y}"/>`}
 $('diagram').innerHTML=html;document.querySelectorAll('[data-edge]').forEach(g=>g.onclick=e=>{e.stopPropagation();selection={type:'edge',index:+g.dataset.edge};showProperties(false);markSelection();properties()});document.querySelectorAll('[data-node]').forEach(g=>{g.onpointerdown=e=>startDrag(e,g.dataset.node);})
}
function properties(){if(selection.type==='edge'){const e=machine.edges[selection.index];if(!e){selection={type:'state',id:machine.start??machine.states[0].id};return properties()}$('properties').innerHTML=`<div class="selection-label">TRANSITION</div><h2 class="property-name">Character expression</h2><label class="prop-field">From<select id="from">${options(e.from)}</select></label><label class="prop-field">To<select id="to">${options(e.to)}</select></label><label class="prop-field">Match expression<input id="edge-label" value="${esc(e.label)}" spellcheck="false"></label><p class="prop-note">One character per transition.<br>Examples: [a-z], [0-9], \\s, \\+<br>Overlapping transitions are reported when testing.</p><button id="delete" class="danger">⌫ Delete transition</button>`;for(const key of ['from','to'])$(key).onchange=()=>{checkpoint();e[key]=$(key).value;changed()};$('edge-label').onchange=()=>{try{matcher($('edge-label').value);checkpoint();e.label=$('edge-label').value;changed()}catch(err){toast(err.message)}}; }else{const s=machine.states.find(s=>s.id===selection.id);const outgoing=machine.edges.map((e,i)=>({...e,index:i})).filter(e=>e.from===s.id);$('properties').innerHTML=`<div class="selection-label">SELECTED STATE</div><h2 class="property-name">${esc(s.name)}</h2><label class="prop-field">State name<input id="state-name" value="${esc(s.name)}"></label>${machine.start===null||s.id===machine.start?`<label class="check"><input type="checkbox" id="initial" ${s.id===machine.start?'checked':''}> Initial state</label>`:''}<label class="check"><input type="checkbox" id="accepting" ${isAccepting(s)?'checked':''}> Accepting state <kbd title="Toggle selected state with A">A</kbd></label><label class="prop-field">Token name<input id="token-name" value="${esc(s.token)}" placeholder="e.g. IDENT"></label><label class="check"><input type="checkbox" id="skip" ${s.skip?'checked':''}> Skip this token</label><p class="prop-note">An accepting state emits a token.<br>Use skip for whitespace or comments.</p><div class="transitions-title">OUTGOING TRANSITIONS <span>(${outgoing.length})</span></div>${outgoing.map(e=>`<button class="transition-item" data-edit-edge="${e.index}">${esc(e.label)} → ${esc(machine.states.find(s=>s.id===e.to).name)}</button>`).join('')}<button id="delete" class="danger">⌫ Delete state</button>`;$('state-name').onchange=()=>{if(!$('state-name').value.trim())return;checkpoint();s.name=$('state-name').value;changed()};$('token-name').onchange=()=>{checkpoint();s.token=$('token-name').value.trim();changed()};if($('initial'))$('initial').onchange=()=>{checkpoint();machine.start=$('initial').checked?s.id:null;changed()};$('accepting').onchange=()=>{checkpoint();setAccepting(s,$('accepting').checked);changed()};$('skip').onchange=()=>{checkpoint();s.skip=$('skip').checked;changed()};document.querySelectorAll('[data-edit-edge]').forEach(b=>b.onclick=()=>{selection={type:'edge',index:+b.dataset.editEdge};render()})}$('delete').onclick=remove}
function options(id){return machine.states.map(s=>`<option value="${esc(s.id)}" ${s.id===id?'selected':''}>${esc(s.name)}</option>`).join('')}
function remove(){if(selection.type==='state'){if(machine.states.length===1){toast('Keep at least one state.');return}checkpoint();machine.states=machine.states.filter(s=>s.id!==selection.id);machine.edges=machine.edges.filter(e=>e.from!==selection.id&&e.to!==selection.id);if(machine.start===selection.id)machine.start=null;selection={type:'state',id:machine.start??machine.states[0].id}}else{checkpoint();machine.edges.splice(selection.index,1);selection={type:'state',id:machine.start??machine.states[0].id}}changed()}
function point(e){return new DOMPoint(e.clientX,e.clientY).matrixTransform($('canvas').getScreenCTM().inverse())}
let drag=null,pan=null,space=false,connectPoint=null,rightStart=null;
function showProperties(show,event){document.body.classList.toggle('properties-hidden',!show);$('toggle-properties').setAttribute('aria-expanded',String(show));if(!show)return;const panel=document.querySelector('.inspector');const target=selection.type==='state'?[...document.querySelectorAll('[data-node]')].find(g=>g.dataset.node===selection.id):document.querySelector(`[data-edge="${selection.index}"]`);const box=target?.getBoundingClientRect(),x=event?.clientX??box?.right??window.innerWidth/2,y=event?.clientY??box?.top??150,bottom=document.querySelector('.tester').getBoundingClientRect().top-12;panel.style.maxHeight=Math.max(180,bottom-80)+'px';panel.style.left=Math.max(10,Math.min(x+16,window.innerWidth-panel.offsetWidth-12))+'px';panel.style.top=Math.max(72,Math.min(y-15,bottom-panel.offsetHeight))+'px'}
function markSelection(){document.querySelectorAll('[data-node]').forEach(g=>g.classList.toggle('selected',selection.type==='state'&&g.dataset.node===selection.id));document.querySelectorAll('[data-edge]').forEach(g=>g.querySelector('.edge').classList.toggle('selected-edge',selection.type==='edge'&&+g.dataset.edge===selection.index))}
function cancelConnect(){source=null;connectPoint=null;rightStart=null;$('modehint').textContent='Right-click a state to connect · Double-click to add · Drag canvas to pan';draw()}
function connectTo(id){checkpoint();machine.edges.push({from:source,to:id,label:'[a-z]'});selection={type:'edge',index:machine.edges.length-1};source=null;connectPoint=null;rightStart=null;$('modehint').textContent='Right-click a state to connect · Double-click to add · Drag canvas to pan';changed();showProperties(true);$('edge-label').focus();$('edge-label').select()}
function startDrag(e,id){e.stopPropagation();if(space||e.button===1){startPan(e);return}if(e.button===2){e.preventDefault();if(source){connectTo(id)}else{source=id;connectPoint=point(e);rightStart={id,x:e.clientX,y:e.clientY};$('modehint').textContent='Click a destination state · Same state for a loop · Esc to cancel';draw()}return}if(e.button!==0)return;if(source){connectTo(id);return}selection={type:'state',id};showProperties(false);const s=machine.states.find(s=>s.id===id),p=point(e);drag={s,dx:p.x-s.x,dy:p.y-s.y,moved:false};markSelection();properties()}
function view(){const v=$('canvas').viewBox.baseVal;return {x:v.x,y:v.y,width:v.width,height:v.height}}
function setView(v){$('canvas').setAttribute('viewBox',`${v.x} ${v.y} ${v.width} ${v.height}`);drawMap()}
function startPan(e){e.preventDefault();showProperties(false);pan={x:e.clientX,y:e.clientY,v:view()};document.body.classList.add('panning')}
$('canvas').onpointerdown=e=>{if(e.button===1||space)startPan(e);else if(e.button===0&&!source&&!e.target.closest('[data-node],[data-edge]')){showProperties(false);startPan(e)}};
$('canvas').oncontextmenu=e=>e.preventDefault();
window.addEventListener('pointermove',e=>{if(pan){const scale=point(e),origin=point({clientX:pan.x,clientY:pan.y});setView({...pan.v,x:pan.v.x+origin.x-scale.x,y:pan.v.y+origin.y-scale.y});return}if(source){connectPoint=point(e);draw();return}if(!drag)return;const p=point(e);if(!drag.moved&&Math.hypot(p.x-drag.dx-drag.s.x,p.y-drag.dy-drag.s.y)<2)return;if(!drag.moved){checkpoint();drag.moved=true}drag.s.x=Math.round(p.x-drag.dx);drag.s.y=Math.round(p.y-drag.dy);draw();drawMap()});
window.addEventListener('pointerup',e=>{if(rightStart&&Math.hypot(e.clientX-rightStart.x,e.clientY-rightStart.y)>6){const node=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-node]');if(node)connectTo(node.dataset.node)}rightStart=null;if(drag?.moved){save();render()}drag=null;pan=null;document.body.classList.remove('panning')});
function add(x,y){const v=view();checkpoint();const id=crypto.randomUUID();machine.states.push({id,name:'q'+machine.states.length,token:'',x:x??v.x+v.width/2,y:y??v.y+v.height/2});selection={type:'state',id};changed();showProperties(true)}
$('canvas').ondblclick=e=>{if(source)return;const node=e.target.closest('[data-node]'),edge=e.target.closest('[data-edge]');if(node||edge){selection=node?{type:'state',id:node.dataset.node}:{type:'edge',index:+edge.dataset.edge};markSelection();properties();showProperties(true,e);return}const p=point(e);add(p.x,p.y)};$('add').onclick=()=>add();
$('undo').onclick=()=>{if(!history.length)return;source=null;future.push(JSON.stringify(machine));machine=JSON.parse(history.pop());changed()};$('redo').onclick=()=>{if(!future.length)return;source=null;history.push(JSON.stringify(machine));machine=JSON.parse(future.pop());changed()};$('reset').onclick=()=>{if(!confirm('Replace this machine with the example? Undo restores your current machine.'))return;checkpoint();source=null;machine=example();changed();fit()};
function fit(){const box=$('diagram').getBBox(),canvas=$('canvas'),panel=0,availableWidth=Math.max(220,canvas.clientWidth-panel-70),availableHeight=Math.max(180,canvas.clientHeight-180);const scale=Math.max((box.width+100)/availableWidth,(box.height+70)/availableHeight);setView({x:box.x+box.width/2-(canvas.clientWidth-panel)/2*scale,y:box.y+box.height/2-(canvas.clientHeight/2+20)*scale,width:canvas.clientWidth*scale,height:canvas.clientHeight*scale})}
$('fit').onclick=fit;$('arrange').onclick=()=>{checkpoint();autoLayout(machine);changed();fit();toast('States and labels arranged. Undo to restore.')};
function zoom(factor,p){showProperties(false);const v=view(),center=p??{x:v.x+v.width/2,y:v.y+v.height/2};if(v.width*factor<160||v.width*factor>30000)return;setView({x:center.x+(v.x-center.x)*factor,y:center.y+(v.y-center.y)*factor,width:v.width*factor,height:v.height*factor})}
$('zoom-in').onclick=()=>zoom(.8);$('zoom-out').onclick=()=>zoom(1.25);$('canvas').addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY>0?1.08:1/1.08,point(e))},{passive:false});
$('toggle-properties').onclick=()=>showProperties(document.body.classList.contains('properties-hidden'));$('close-properties').onclick=()=>showProperties(false);$('toggle-tester').onclick=()=>{const collapsed=document.body.classList.toggle('tester-collapsed');$('toggle-tester').textContent=collapsed?'⌃':'⌄';$('toggle-tester').setAttribute('aria-expanded',String(!collapsed))};
function drawMap(){
 const map=$('minimap'),v=view(),xs=machine.states.map(s=>s.x),ys=machine.states.map(s=>s.y);let x=Math.min(...xs,v.x)-100,y=Math.min(...ys,v.y)-120,w=Math.max(...xs,v.x+v.width)-x+100,h=Math.max(...ys,v.y+v.height)-y+100;const ratio=170/106;if(w/h<ratio){const next=h*ratio;x-=(next-w)/2;w=next}else{const next=w/ratio;y-=(next-h)/2;h=next}map.setAttribute('viewBox',`${x} ${y} ${w} ${h}`);
 map.innerHTML=machine.edges.map(e=>{const a=machine.states.find(s=>s.id===e.from),b=machine.states.find(s=>s.id===e.to);return `<line x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}"/>`}).join('')+machine.states.map(s=>`<circle cx="${s.x}" cy="${s.y}" r="24"/>`).join('')+`<rect class="map-viewport" x="${v.x}" y="${v.y}" width="${v.width}" height="${v.height}"/>`;
}
let mapDragging=false,mapTransform=null;
function navigateMap(e){const p=new DOMPoint(e.clientX,e.clientY).matrixTransform(mapTransform??$('minimap').getScreenCTM().inverse()),v=view();setView({...v,x:p.x-v.width/2,y:p.y-v.height/2})}
$('minimap').onpointerdown=e=>{e.preventDefault();mapDragging=true;mapTransform=$('minimap').getScreenCTM().inverse();$('minimap').setPointerCapture(e.pointerId);navigateMap(e)};$('minimap').onpointermove=e=>{if(mapDragging)navigateMap(e)};$('minimap').onpointerup=()=>{mapDragging=false;mapTransform=null};$('minimap').onpointercancel=()=>{mapDragging=false;mapTransform=null};
function test(){try{const all=tokenize(machine,$('input').value);const tokens=all.filter(t=>!t.skip||$('show-skipped').checked);$('token-count').textContent=tokens.length+' tokens';$('tokens').innerHTML=tokens.length?tokens.map(t=>`<div class="token ${t.token==='ERROR'?'error':t.token==='NUMBER'?'number':''}" title="Offset ${t.offset}${t.skip?' · skipped':''}"><b>${esc(t.token)}</b>${esc(JSON.stringify(t.value))}</div>`).join(''):'<span class="empty">Type some input to see tokens.</span>'}catch(err){$('tokens').innerHTML=`<span class="empty">${esc(err.message)}</span>`;$('token-count').textContent='Needs attention'}}$('input').oninput=test;$('show-skipped').onchange=test;
function exportSvg(){const svg=$('canvas').cloneNode(true);svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.setAttribute('width','820');svg.setAttribute('height','510');const box=$('diagram').getBBox();svg.setAttribute('viewBox',`${box.x-30} ${box.y-30} ${box.width+60} ${box.height+60}`);svg.querySelector('.connection-preview')?.remove();const style=document.createElementNS('http://www.w3.org/2000/svg','style');style.textContent='.edge{fill:none;stroke:#65755d;stroke-width:1.6;marker-end:url(#arrow)}.edge-hit{display:none}.edge-text{font:11px monospace;fill:#53634b;paint-order:stroke;stroke:white;stroke-width:6px}.node circle{fill:#f9fbf5;stroke:#718664;stroke-width:1.7}.node .inner{fill:none}.node text{text-anchor:middle;font:12px sans-serif;fill:#425838}.node .token-label{font:9px monospace}';svg.prepend(style);return new XMLSerializer().serializeToString(svg)}
function exportText(){return $('format').value==='tex'?toTikz(machine,$('standalone').checked):$('format').value==='json'?JSON.stringify(machine,null,2):exportSvg()}
function preview(){try{$('export-preview').value=exportText();$('download').textContent='↓ Download .'+$('format').value;$('standalone-label').style.visibility=$('format').value==='tex'?'visible':'hidden'}catch(err){toast(err.message)}}
function openExport(){preview();$('export-dialog').showModal()}$('export').onclick=openExport;$('close-dialog').onclick=()=>$('export-dialog').close();$('format').onchange=preview;$('standalone').onchange=preview;$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(exportText());toast('Copied to clipboard.')}catch{toast('Select and copy the export preview.')}};$('download').onclick=()=>{const ext=$('format').value;const blob=new Blob([exportText()],{type:ext==='svg'?'image/svg+xml':ext==='json'?'application/json':'application/x-tex'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='lexer.'+ext;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{try{const f=$('file').files[0];if(!f)return;if(f.size>1000000)throw Error('Machine file is too large (maximum 1 MB).');const next=validate(JSON.parse(await f.text()));checkpoint();machine=next;selection={type:'state',id:machine.start??machine.states[0].id};changed();fit();toast('Machine imported.')}catch(err){toast(err.message)}$('file').value=''};
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('export-dialog').open){e.preventDefault();cancelConnect();showProperties(false);return}if(e.target.matches('input,textarea,select')||$('export-dialog').open)return;if(e.key.toLowerCase()==='a'&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.repeat&&selection.type==='state'){e.preventDefault();const state=machine.states.find(s=>s.id===selection.id);checkpoint();setAccepting(state,!isAccepting(state));changed();return}if(e.key==='Delete'){e.preventDefault();remove()}if(e.key==='Escape'){cancelConnect();showProperties(false)}if(e.code==='Space'){e.preventDefault();space=true;document.body.classList.add('pan-ready')}if((e.ctrlKey||e.metaKey)&&e.key==='z'){e.preventDefault();$(e.shiftKey?'redo':'undo').click()}});window.addEventListener('keyup',e=>{if(e.code==='Space'){space=false;document.body.classList.remove('pan-ready')}});window.addEventListener('blur',()=>{space=false;pan=null;drag=null;document.body.classList.remove('pan-ready','panning')});render();requestAnimationFrame(fit);
